const QUEUE_FILE_NAME = 'member_lookup_bridge_gate4a_pending_queue.jsonl';
const SOURCE_LABEL = 'google_sheets_uat_gate4a';

const FIELD_ALIASES = {
  name: ['Full Name', 'Name'],
  memberNo: ['AutoCount MemberNo', 'Phone/Member Number', 'Phone Member Number', 'Phone Number', 'Member Number', 'Submitted Member Number', 'Submitted Member No', 'Mobile Number'],
  email: ['Email Address', 'Email'],
  birthdayMonth: ['Birthday Month', 'Birthday', 'Date of Birth', 'DOB'],
  marketingConsent: ['Marketing Consent', 'consent_status', 'Consent Status'],
  pdpa: ['PDPA Acknowledged', 'PDPA', 'PDPA Status'],
  rowNumber: ['row_number', 'Row Number', 'RowNumber']
};

const MONTH_TO_ISO_DOB = {
  january: '2000-01-01',
  february: '2000-02-01',
  march: '2000-03-01',
  april: '2000-04-01',
  may: '2000-05-01',
  june: '2000-06-01',
  july: '2000-07-01',
  august: '2000-08-01',
  september: '2000-09-01',
  october: '2000-10-01',
  november: '2000-11-01',
  december: '2000-12-01'
};

const items = $input.all();
if (items.length !== 1) throw new Error('gate4a_requires_exactly_one_approved_source_row');

const row = items[0].json;
const pick = (aliases) => {
  for (const key of aliases) {
    if (Object.prototype.hasOwnProperty.call(row, key)) return row[key];
  }
  return undefined;
};
const clean = (value) => String(value ?? '').trim();

const requiredName = clean(pick(FIELD_ALIASES.name));
const submittedMemberNo = clean(pick(FIELD_ALIASES.memberNo));
const requiredEmail = clean(pick(FIELD_ALIASES.email));
const birthdayMonthRaw = clean(pick(FIELD_ALIASES.birthdayMonth));
const marketingConsentRaw = clean(pick(FIELD_ALIASES.marketingConsent));
const pdpaRaw = clean(pick(FIELD_ALIASES.pdpa));
const rowNumber = Number(pick(FIELD_ALIASES.rowNumber));
const birthdayMonthKey = birthdayMonthRaw.toLowerCase();
const derivedDobIso = MONTH_TO_ISO_DOB[birthdayMonthKey];

if (!requiredName) throw new Error('gate4a_full_name_required');
if (!requiredEmail) throw new Error('gate4a_email_address_required');
if (!derivedDobIso) throw new Error('gate4a_birthday_month_must_be_valid_month_name');
if (!/^[0-9]{6,20}$/.test(submittedMemberNo)) throw new Error('gate4a_autocount_member_no_must_be_6_to_20_digits');
if (/imported/i.test(pdpaRaw)) throw new Error('gate4a_imported_pdpa_marker_blocked');
if (pdpaRaw.toLowerCase() !== 'yes') throw new Error('gate4a_pdpa_must_be_yes');
if (!Number.isInteger(rowNumber) || rowNumber < 1) throw new Error('gate4a_safe_row_number_required');

const dummySourceText = [requiredName, submittedMemberNo, requiredEmail, birthdayMonthRaw, marketingConsentRaw, pdpaRaw].join(' ').toLowerCase();
if (/\b(dummy|fixture|placeholder|rehearsal|sample|synthetic)\b/.test(dummySourceText)) {
  throw new Error('gate4a_source_row_must_be_real_non_dummy');
}

const submittedMemberNoBase64 = Buffer.from(submittedMemberNo, 'utf8').toString('base64');
const now = new Date();
const createdAt = now.toISOString();
const timeoutAt = new Date(now.getTime() + 15 * 60 * 1000).toISOString();
const sourceReference = SOURCE_LABEL;
const sourceRowRef = `row_${rowNumber}`;
const intakeId = `gate4a_${sourceRowRef}`;

const fnv1a = (text) => {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
};

const payloadHash = `fnv1a_${fnv1a(JSON.stringify({
  intake_source: SOURCE_LABEL,
  source_reference: sourceReference,
  source_row_ref: sourceRowRef,
  row_number: rowNumber,
  intake_id: intakeId,
  state: 'PENDING_LOOKUP',
  submitted_member_no_base64_utf8: submittedMemberNoBase64,
  pdpa_status: 'yes'
}))}`;

const queueRow = {
  job_id: `gate4a_${payloadHash}`,
  intake_source: SOURCE_LABEL,
  source_reference: sourceReference,
  source_row_ref: sourceRowRef,
  row_number: rowNumber,
  intake_id: intakeId,
  state: 'PENDING_LOOKUP',
  submitted_member_no_base64_utf8: submittedMemberNoBase64,
  consent_status: 'marketing_consent_not_queued',
  pdpa_status: 'yes',
  payload_hash: payloadHash,
  attempt: 0,
  max_attempts: 1,
  created_at: createdAt,
  updated_at: createdAt,
  timeout_at: timeoutAt
};

const allowed = ['job_id', 'intake_source', 'source_reference', 'source_row_ref', 'row_number', 'intake_id', 'state', 'submitted_member_no_base64_utf8', 'consent_status', 'pdpa_status', 'payload_hash', 'attempt', 'max_attempts', 'created_at', 'updated_at', 'timeout_at'];
const orderedQueueRow = Object.fromEntries(allowed.map((field) => [field, queueRow[field]]));
const jsonl = `${JSON.stringify(orderedQueueRow)}\n`;

return [{
  json: {
    gate: 'gate4a_real_queue_write_pre_bridge_check',
    queue_row_count: 1,
    queue_file_name: QUEUE_FILE_NAME,
    no_row_values_printed: true,
    ac2_lookup_invoked: false,
    n8n_result_mapping_run: false,
    workflow_activation: 'inactive'
  },
  binary: {
    data: {
      data: Buffer.from(jsonl, 'utf8').toString('base64'),
      mimeType: 'application/x-jsonlines',
      fileName: QUEUE_FILE_NAME
    }
  }
}];
